import ast, json, math, pathlib, sys

MODULE = "packages/fcos-projections/fcos_owner_freshness.py"

def load():
    src = pathlib.Path(MODULE).read_text(encoding="utf-8")
    tree = ast.parse(src)
    names = [n.name for n in tree.body if isinstance(n, ast.FunctionDef)]
    assert "g3_margin_report" in names, "g3_margin_report missing from %s" % MODULE
    ns = {"__name__": "g3_mod"}
    exec(compile(src, MODULE, "exec"), ns)
    return ns["g3_margin_report"]

def main():
    fn = load()
    r1 = fn(3.2491, 3.007)
    assert r1 == {"ok": True, "margin": 0.2421, "band": "inside"}, r1
    r2 = fn(5.044, 3.007)
    assert r2 == {"ok": False, "margin": 2.037, "band": "outside"}, r2
    r3 = fn(3.1188)
    assert r3["band"] == "inside" and r3["ok"] is True, r3
    for bad in (float("nan"), float("inf"), float("-inf")):
        try:
            fn(bad)
        except ValueError as exc:
            assert "non-finite" in str(exc), exc
        else:
            raise AssertionError("expected ValueError for %r" % bad)
    print("ACCEPT")

main()

